v_lshlrev_b32 v0, 9, v0                            // 1. N offset: nOffset = nIdx * nStride(512)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v0, 3, v0                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(8)
v_lshrrev_b32 v1, 4, v1                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v0, v1, 5, v0                       // 5. K offset: lrKOffset = kIdx * mStride(32); 6. offset in wave: lrOffset = bnOffset + lrKOffset
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v4, 5, v[vgprSerial-768]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(32)
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v4, 1, v4                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
s_mov_b32 s65, 137216                              // seg interleave: component byte offset = wtid0 * (fA+fB)
v_mul_lo_u32 v6, s65, v4                           // seg interleave: component byte offset = wtid0 * (fA+fB)
/* lr0I */
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_and_b32 v2, 31, v[vgprSerial-768]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v1, 15, v2                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v1, 2, v1                            // 1. N offset: nOffset = nIdx * nStride(4)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v1, 3, v1                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(8)
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v3, 5, v[vgprSerial-768]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(32)
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 1, v3                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
                                                   // MXSA M-half jump (post-pad) (dup assign opt.)
v_mul_lo_u32 v8, s65, v3                           // MXSA M-half jump (post-pad)
/* lr1J */
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_and_b32 v3, 31, v[vgprSerial-768]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v2, 15, v3                               // 1. N offset: nIdx = wtid % MI_N(16)
v_lshlrev_b32 v2, 9, v2                            // 1. N offset: nOffset = nIdx * nStride(512)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v2, 2, v2                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(4)
v_lshrrev_b32 v3, 4, v3                            // 5. K offset: kIdx = wtid / (MIN(16) * MIBB(1))
v_lshl_add_u32 v2, v3, 5, v2                       // 5. K offset: lrKOffset = kIdx * mStride(32); 6. offset in wave: lrOffset = bnOffset + lrKOffset
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v7, 6, v[vgprSerial-768]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v7, 1, v7                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
                                                   // seg interleave: component byte offset = wtid0 * (fA+fB) (dup assign opt.)
v_mul_lo_u32 v10, s65, v7                          // seg interleave: component byte offset = wtid0 * (fA+fB)
/* lr1J */
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_and_b32 v4, 31, v[vgprSerial-768]                // 0. thread id in wave: wtid = tid % wavelength(32)
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v3, 31, v4                               // 1. N offset: nIdx = wtid % MI_N(32)
v_lshlrev_b32 v3, 2, v3                            // 1. N offset: nOffset = nIdx * nStride(4)
/* Skip. 2. block offset: bnOffset = 0 when num1DBlocks = 1 */
v_lshlrev_b32 v3, 2, v3                            // 4. apply VectorWidth: bnOffset = bnOffset * vw(4)
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v5, 6, v[vgprSerial-768]             // 7. wave offset in N dimen: wtid = tid / dividedForWaveId(64)
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_and_b32 v5, 1, v5                                // 7. wave offset in M dimen: wtid0 = wtid / num1DWaves(2)
v_lshl_add_u32 v3, v5, 9, v3                       // 7. wave offset in M dimen: wOffset = wtid0 * W0Stride(512); 7. final local read offset: flrOffset = lrOffset + WOffset

/* local read addresses: final offsets a */
s_set_vgpr_msb 12                                  // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v4, 5, v[vgprSerial-768]             // 4 = Serial / 32
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v4, 2, v4                            // LSU offset: Get LSU wave_id
s_mov_b32 s65, 512                                 // LSU offset: stride = lsuStride(512) when umlds==True
v_mul_lo_u32 v4, s65, v4                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT0+PAD)
s_set_vgpr_msb 128                                 // src0: 0, src1: 0, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrA-512], v4, v0     // Final Offset: offset = (lro0+lsuoffset)*bpeDS
s_set_vgpr_msb 32904                               // src0: 0, src1: 2, src2: 0, dst: 2
v_lshrrev_b32 v[vgprLocalReadAddrA-512], 1, v[vgprLocalReadAddrA-512] //  (multiple bpe)
s_set_vgpr_msb 34824                               // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v5, 11, v[vgprLocalReadAddrA-512]    // Final Offset: padding 16 per block 2048
s_set_vgpr_msb 2208                                // src0: 0, src1: 0, src2: 2, dst: 2
v_lshl_add_u32 v[vgprLocalReadAddrA-512], v5, 4, v[vgprLocalReadAddrA-512] // Final Offset: padding 16 per block 2048
s_set_vgpr_msb 41096                               // src0: 0, src1: 2, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrA-512], v6, v[vgprLocalReadAddrA-512] // seg interleave: += wtid0*(fA+fB) (post-pad)

/* local read addresses: final offsets mxsa */
s_set_vgpr_msb 34828                               // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-768]             // 0 = Serial / 32
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
s_mov_b32 s65, 4096                                // LSU offset: stride = lsuStride(16)*(MTMXSA(256) + PADMXSA(0))
v_mul_lo_u32 v0, s65, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT0+PAD)
s_set_vgpr_msb 128                                 // src0: 0, src1: 0, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrMXSA-512], v0, v1  // Final Offset: offset = (lro0+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)
s_set_vgpr_msb 32776                               // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v4, 8, v[vgprLocalReadAddrMXSA-512]  // Final Offset: padding 16 per block 256
s_set_vgpr_msb 2208                                // src0: 0, src1: 0, src2: 2, dst: 2
v_lshl_add_u32 v[vgprLocalReadAddrMXSA-512], v4, 4, v[vgprLocalReadAddrMXSA-512] // Final Offset: padding 16 per block 256
s_set_vgpr_msb 41096                               // src0: 0, src1: 2, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrMXSA-512], v8, v[vgprLocalReadAddrMXSA-512] // seg interleave: += wtid0*(fA+fB) (post-pad)

/* local read addresses: final offsets mxsb */
s_set_vgpr_msb 34828                               // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-768]             // 0 = Serial / 32
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
                                                   // LSU offset: stride = lsuStride(16)*(MTMXSB(256) + PADMXSB(0)) (dup assign opt.)
v_mul_lo_u32 v0, s65, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
s_set_vgpr_msb 128                                 // src0: 0, src1: 0, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrMXSB-512], v0, v3  // Final Offset: offset = (lro1+lsuoffset)*bpeDS
                                                   //  (bpe is 1, do nothing)

/* local read addresses: final offsets b */
s_set_vgpr_msb 32780                               // src0: 0, src1: 3, src2: 0, dst: 0
v_lshrrev_b32 v0, 5, v[vgprSerial-768]             // 0 = Serial / 32
s_set_vgpr_msb 3072                                // src0: 0, src1: 0, src2: 0, dst: 0
v_lshrrev_b32 v0, 2, v0                            // LSU offset: Get LSU wave_id
s_mov_b32 s65, 512                                 // LSU offset: stride = lsuStride(512) when umlds==True
v_mul_lo_u32 v0, s65, v0                           // LSU offset: lsuoffset = wave_id*lsuStride*(MT1+PAD)
s_set_vgpr_msb 128                                 // src0: 0, src1: 0, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrB-512], v0, v2     // Final Offset: offset = (lro1+lsuoffset)*bpeDS
s_set_vgpr_msb 32904                               // src0: 0, src1: 2, src2: 0, dst: 2
v_lshrrev_b32 v[vgprLocalReadAddrB-512], 1, v[vgprLocalReadAddrB-512] //  (multiple bpe)
s_set_vgpr_msb 34824                               // src0: 0, src1: 2, src2: 0, dst: 0
v_lshrrev_b32 v1, 10, v[vgprLocalReadAddrB-512]    // Final Offset: padding 16 per block 1024
s_set_vgpr_msb 2208                                // src0: 0, src1: 0, src2: 2, dst: 2
v_lshl_add_u32 v[vgprLocalReadAddrB-512], v1, 4, v[vgprLocalReadAddrB-512] // Final Offset: padding 16 per block 1024
s_set_vgpr_msb 41096                               // src0: 0, src1: 2, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadAddrB-512], v10, v[vgprLocalReadAddrB-512] // seg interleave: += wtid0*(fA+fB) (post-pad)

/* local read addresses: declare addresses a */
v_add_co_u32 v[vgprLocalReadAddrA+0-512], vcc_lo, 0x0, v[vgprLocalReadAddrA+0-512] //  += LdsOffsetA (lower)
v_add_nc_u32 v[vgprLocalReadAddrA+1-512], 65536, v[vgprLocalReadAddrA-512] // Final Offset Plus 64K

/* local read addresses: declare addresses mxsa */
v_add_co_u32 v[vgprLocalReadAddrMXSA+0-512], vcc_lo, 0x20600, v[vgprLocalReadAddrMXSA+0-512] //  += LdsOffsetMXSA (lower)

/* local read addresses: declare addresses mxsb */
v_add_co_u32 v[vgprLocalReadAddrMXSB+0-512], vcc_lo, 0x43000, v[vgprLocalReadAddrMXSB+0-512] //  += LdsOffsetMXSB (lower)

/* local read addresses: declare addresses b */
v_add_co_u32 v[vgprLocalReadAddrB+0-512], vcc_lo, 0x10200, v[vgprLocalReadAddrB+0-512] //  += LdsOffsetB (lower)
v_add_nc_u32 v[vgprLocalReadAddrB+1-512], 65536, v[vgprLocalReadAddrB-512] // Final Offset Plus 64K
s_set_vgpr_msb 35016                               // src0: 0, src1: 2, src2: 0, dst: 3
v_add_nc_u32 v[vgprLocalReadSwapAddrA-768], 33024, v[vgprLocalReadAddrA-512] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 51403                               // src0: 3, src1: 2, src2: 0, dst: 3
v_xor_b32 v[vgprLocalReadSwapAddrA-768], v[vgprLocalReadSwapAddrA-768], v[vgprLocalReadAddrA-512] // xor both lds buffer offsets to enable swapping
s_set_vgpr_msb 52168                               // src0: 0, src1: 2, src2: 0, dst: 3
v_add_nc_u32 v[vgprLocalReadSwapAddrMXSA-768], 2304, v[vgprLocalReadAddrMXSA-512] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 51403                               // src0: 3, src1: 2, src2: 0, dst: 3
v_xor_b32 v[vgprLocalReadSwapAddrMXSA-768], v[vgprLocalReadSwapAddrMXSA-768], v[vgprLocalReadAddrMXSA-512] // xor both lds buffer offsets to enable swapping
s_set_vgpr_msb 52168                               // src0: 0, src1: 2, src2: 0, dst: 3
v_add_nc_u32 v[vgprLocalReadSwapAddrB-768], 33280, v[vgprLocalReadAddrB-512] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 51403                               // src0: 3, src1: 2, src2: 0, dst: 3
v_xor_b32 v[vgprLocalReadSwapAddrB-768], v[vgprLocalReadSwapAddrB-768], v[vgprLocalReadAddrB-512] // xor both lds buffer offsets to enable swapping
s_set_vgpr_msb 52168                               // src0: 0, src1: 2, src2: 0, dst: 3
v_add_nc_u32 v[vgprLocalReadSwapAddrMXSB-768], 4096, v[vgprLocalReadAddrMXSB-512] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 51403                               // src0: 3, src1: 2, src2: 0, dst: 3
v_xor_b32 v[vgprLocalReadSwapAddrMXSB-768], v[vgprLocalReadSwapAddrMXSB-768], v[vgprLocalReadAddrMXSB-512] // xor both lds buffer offsets to enable swapping

/******************************************/
/* Local Write Addresses                  */
/******************************************/

/* local write addresses: first offset a */

/* local write addresses: first offset b */
s_lshr_b32 s[sgprNumWorkGroups0], s[sgprSizesFree+0], 8 // s[sgprNumWorkGroups0] = s[sgprSizesFree+0] / 256
s_and_b32 s65, 255, s[sgprSizesFree+0]             // s65 = s[sgprSizesFree+0] % 256
s_cmp_gt_u32 s65, 0                                // Check if remainder > 0
s_addc_u32 s[sgprNumWorkGroups0], s[sgprNumWorkGroups0], 0 // Increment if remainder > 0
s_lshr_b32 s[sgprNumWorkGroups1], s[sgprSizesFree+1], 8 // s[sgprNumWorkGroups1] = s[sgprSizesFree+1] / 256
s_and_b32 s65, 255, s[sgprSizesFree+1]             // s65 = s[sgprSizesFree+1] % 256
s_cmp_gt_u32 s65, 0                                // Check if remainder > 0
s_addc_u32 s[sgprNumWorkGroups1], s[sgprNumWorkGroups1], 0 // Increment if remainder > 0
s_and_b32 s65, s[sgprArgType], 0xff                // mask ArgType domain (bits 8+ are internal flags)
s_cmp_eq_u32 s65, 2                                // ArgType == 2 ?
s_cbranch_scc0 label_SkipWaitForUserArgs_2         // skip wait if ArgType != 2
s_wait_kmcnt 0                                     // wait for 16/0 bytes of kern args
label_SkipWaitForUserArgs_2:  /// skip kern args wait if ArgType != 2

/* Early stop if N(SizeFreeJ) == 0 */
s_cmp_eq_u32 s[sgprSizeJ], 0
s_cbranch_scc0 label_NoEarlyStop_N0
label_EarlyStop_if_N_is_0:
s_endpgm
label_NoEarlyStop_N0:

/* Early stop padded work-groups in a boundary cluster (grid rounded up to ClusterDim) */
s_cmp_ge_u32 s[sgprWorkGroup0], s[sgprNumWorkGroups0] // padded if WorkGroup0 >= tilesM
s_cbranch_scc1 label_ClusterPad_EarlyStop_1
s_and_b32 s20, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s20, s[sgprNumWorkGroups1], s20          // tilesN * GSU
s_cmp_ge_u32 s[sgprWorkGroup1], s20                // padded if WorkGroup1 >= tilesN*GSU
s_cbranch_scc1 label_ClusterPad_EarlyStop_1
s_branch label_ClusterPad_NoEarlyStop_1
label_ClusterPad_EarlyStop_1:
s_endpgm                                           // padded work-group: exit before any load/barrier
label_ClusterPad_NoEarlyStop_1:
s_branch label_MultiGemmEnd                        // Already using 3D WorkGroups, skip remap

/* remap wg from 1D(idxWG012) to 3D(wg2,wg1,wg0) */
/* wg2 = idxWG012 * smallMagicNumber(1/(numWG0*numWG1)) */
s_mul_i32 s20, s[sgprNumWorkGroups0], s[sgprNumWorkGroups1]
s_and_b32 s21, s[sgprGSU], 0xfff                   // Restore GSU
s_mul_i32 s20, s20, s21
s_set_vgpr_msb 0                                   // src0: 0, src1: 0, src2: 0, dst: 0
v_cvt_f32_u32 v0, s20                              // s20 = s[sgprWorkGroup0] / s20
v_rcp_iflag_f32 v0, v0                             // s20 = s[sgprWorkGroup0] / s20
v_mov_b32 v1, 0x4f7ffffe                           // 2^32 - 512
v_mul_f32 v0, v1, v0                               // 2^32 / divisor
v_cvt_u32_f32 v0, v0                               // s20 = s[sgprWorkGroup0] / s20
v_mul_lo_u32 v1, v0, s20                           // refine 2^32 / divisor
v_sub_nc_u32 v1, 0, v1                             // refine 2^32 / divisor
v_mul_hi_u32 v1, v0, v1                            // refine 2^32 / divisor
v_add_nc_u32 v0, v0, v1                            // refine 2^32 / divisor
v_mul_hi_u32 v0, s[sgprWorkGroup0], v0             // s20 = s[sgprWorkGroup0] / s20
v_mul_lo_u32 v1, v0, s20                           // s20 = s[sgprWorkGroup0] / s20
v_sub_nc_u32 v1, s[sgprWorkGroup0], v1             // s20 = s[sgprWorkGroup0] / s20
v_cmp_ge_u32 vcc_lo, v1, s20                       // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s20                           // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_ge_u32 vcc_lo, v1, s20                       // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s20                           // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_readfirstlane_b32 s20, v0                        // quotient
s_mov_b32 s[sgprWorkGroup2], s20
/* idxWG01 = idxWG012 - wg2 * numWG0 * numWG1 */
s_mul_i32 s20, s[sgprNumWorkGroups1], s[sgprNumWorkGroups0]
s_mul_i32 s20, s20, s[sgprWorkGroup2]
s_mul_i32 s20, s20, s21
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s20
/* wg1 = idxWG01 * smallMagicNumber(1/numWG0) */
v_cvt_f32_u32 v0, s[sgprNumWorkGroups0]            // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_rcp_iflag_f32 v0, v0                             // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mov_b32 v1, 0x4f7ffffe                           // 2^32 - 512
v_mul_f32 v0, v1, v0                               // 2^32 / divisor
v_cvt_u32_f32 v0, v0                               // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_lo_u32 v1, v0, s[sgprNumWorkGroups0]         // refine 2^32 / divisor
v_sub_nc_u32 v1, 0, v1                             // refine 2^32 / divisor
v_mul_hi_u32 v1, v0, v1                            // refine 2^32 / divisor
v_add_nc_u32 v0, v0, v1                            // refine 2^32 / divisor
v_mul_hi_u32 v0, s[sgprWorkGroup0], v0             // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_mul_lo_u32 v1, v0, s[sgprNumWorkGroups0]         // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_sub_nc_u32 v1, s[sgprWorkGroup0], v1             // s20 = s[sgprWorkGroup0] / s[sgprNumWorkGroups0]
v_cmp_ge_u32 vcc_lo, v1, s[sgprNumWorkGroups0]     // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s[sgprNumWorkGroups0]         // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_cmp_ge_u32 vcc_lo, v1, s[sgprNumWorkGroups0]     // remainder >= divisor?
s_mov_b32 exec_lo, vcc_lo                          // remainder >= divisor?
v_add_nc_u32 v0, 1, v0                             // quotient + 1
v_sub_nc_u32 v1, v1, s[sgprNumWorkGroups0]         // remainder - divisor
s_mov_b32 exec_lo, -1                              // Reset exec
v_readfirstlane_b32 s20, v0                        // quotient
s_mov_b32 s[sgprWorkGroup1], s20
/* wg0 = idxWG01 - wg1 * numWG0 */
s_mul_i32 s20, s20, s[sgprNumWorkGroups0]
s_sub_u32 s[sgprWorkGroup0], s[sgprWorkGroup0], s20

/* Early stop if wg exceed */
s_cmp_ge_u32 s[sgprWorkGroup2], s[sgprSizesFree+2]
s_cbranch_scc0 label_NoEarlyStop_wgExceed
label_EarlyStop_if_wg_exceed:
s_endpgm
label_NoEarlyStop_wgExceed:

label_MultiGemmEnd:
